/*
 * ring_$open_internal - open a ring channel for a set of packet-type ranges
 *
 * Original address: 0x00E76B7C (module-local; the SAU2 map has no symbol
 * here; was Ghidra ring_$open_internal)
 * Size: 628 bytes (0x00E76B7C .. 0x00E76DF1)
 * Generated by: Claude Opus 5.5
 *
 * Callers: RING_$SVC_OPEN (0x00E76E0E, is_os false) and RING_$OPEN_OS
 * (0x00E77C08, `st -(SP)`).  A5 = 0xE86400 (RING_$CTL).
 *
 * Frame (link.w A6,-0x24): (0x8,A6) is_os (D2b), (0xa,A6) unit_ptr (A3),
 * (0xe,A6) args (D6), (0x12,A6) status (D7); (-0x24) the range cursor,
 * (-0x8) the allocated socket, (-0x6) the mask copy.
 *
 * Blocks:
 *   0x00E76B9A-0x00E76BCE  *unit > 1 -> invalid unit; version > 1 (signed)
 *                          -> driver version mismatch; *unit > 1 again
 *   0x00E76BD2-0x00E76BD8  A2 = RING_$CTL.units[*unit] (mulu.w #0x244)
 *   0x00E76BDC             ring_$disable_interrupts() (0x00E7667C)
 *   0x00E76BE0-0x00E76C1C  under tx_exclusion: first open -> ring_$do_start
 *                          unless STARTED (else status ok), open_count = 1;
 *                          later opens -> status ok, open_count++
 *   0x00E76C20-0x00E76C3C  tmask bit 0 clear -> ring_$set_hw_mask(unit,
 *                          tmask | 0x81)
 *   0x00E76C3E-0x00E76C4E  release tx_exclusion; status != 0 -> return
 *   0x00E76C52-0x00E76C78  under rx_exclusion: first closed channel 1..10;
 *                          none -> no channels (0x00E76D48)
 *   0x00E76C7A-0x00E76C9A  pkt_type_cnt + count > 0x20 (zero-extended,
 *                          unsigned) -> no channels
 *   0x00E76C9E-0x00E76D18  for k = 1..count: low > high (unsigned) ->
 *                          invalid svc packet type; overlap with an entry in
 *                          use -> packet type in use; else pkt_types[cnt + k]
 *                          = (low, high, channel)
 *   0x00E76D1C-0x00E76D66  is_os -> socket 0xE1; else SOCK_$ALLOCATE_USER(
 *                          &sock, 8, 8, 8, 0x400), failure -> no channels,
 *                          success -> clear SOCK_FLAG_OPEN in the socket
 *   0x00E76D6C-0x00E76D90  channel = { asid, socket, version, open };
 *                          pkt_type_cnt += count
 *   0x00E76D94-0x00E76D9E  release rx_exclusion
 *   0x00E76DA0-0x00E76DCA  ok -> args->channel = channel; args->ec2_handle =
 *                          EC2_$REGISTER_EC1(&socket->ec, status)
 *   0x00E76DCE-0x00E76DE2  failed -> open_count-- under tx_exclusion
 *
 * Quirks kept: a failure part way through the range loop or in the socket
 * allocation leaves the ranges already written in the table (the count is
 * only advanced at 0x00E76D90); the channel word and the EC2 handle are
 * written over the request's own fields.
 */

#include "ring/ring_internal.h"
#include "sock/sock.h"
#include "ec/ec.h"
#include "ml/ml.h"
#include "proc1/proc1.h"

void ring_$open_internal(boolean is_os, uint16_t *unit_ptr,
                         ring_$open_args_t *args, status_$t *status_ret)
{
    ring_unit_t *unit_data;         /* A2 */
    uint16_t channel;               /* D3w */
    uint16_t socket;                /* D2w */
    int16_t remaining;              /* D4w */
    int16_t k;                      /* D5w */
    ring_$pkt_range_t *range;       /* (-0x24,A6) */
    uint16_t mask;                  /* (-0x6,A6) */
    uint16_t sock_num;              /* (-0x8,A6) */
    ring_channel_t *chan;
    sock_$sock_t *sock;

    /* 0x00E76B9A-0x00E76BA8 */
    if (*unit_ptr > 1) {
        *status_ret = status_$ring_invalid_unit_num;
        return;
    }
    /* 0x00E76BAC-0x00E76BBC: cmpi.w #1 / ble, signed */
    if (args->hdr.in.version > 1) {
        *status_ret = status_$ring_driver_version_mismatch;
        return;
    }
    /* 0x00E76BC0-0x00E76BCE: the unit is tested a second time */
    if (*unit_ptr > 1) {
        *status_ret = status_$ring_invalid_unit_num;
        return;
    }

    /* 0x00E76BD2-0x00E76BD8 */
    unit_data = &RING_$CTL.units[*unit_ptr];

    /* 0x00E76BDC: bsr 0x00E7667C (misnamed, see ring/helpers.c) */
    ring_$disable_interrupts();

    /* 0x00E76BE0-0x00E76BEA */
    ML_$EXCLUSION_START(&unit_data->tx_exclusion);

    /* 0x00E76BEC-0x00E76C1C */
    if (unit_data->open_count == 0) {
        if ((unit_data->state_flags & RING_UNIT_STARTED) == 0) {
            /* 0x00E76BFA-0x00E76C06: a result slot is reserved and dropped */
            ring_$do_start(*unit_ptr, unit_data, status_ret);
        } else {
            *status_ret = status_$ok;           /* 0x00E76C0C */
        }
        unit_data->open_count = 1;              /* 0x00E76C10 */
    } else {
        *status_ret = status_$ok;               /* 0x00E76C18 */
        unit_data->open_count++;                /* 0x00E76C1C */
    }

    /* 0x00E76C20-0x00E76C3C: btst.b #0,(0x33,A2) = bit 0 of the tmask word */
    if ((unit_data->tmask & 1) == 0) {
        mask = (uint16_t)(unit_data->tmask | 0x81);
        ring_$set_hw_mask(*unit_ptr, mask);
    }

    /* 0x00E76C3E-0x00E76C4E */
    ML_$EXCLUSION_STOP(&unit_data->tx_exclusion);
    if (*status_ret != status_$ok) {
        return;
    }

    /* 0x00E76C52-0x00E76C5C */
    ML_$EXCLUSION_START(&unit_data->rx_exclusion);

    /* 0x00E76C5E-0x00E76C78: the first channel whose flag byte is not set */
    channel = 1;
    while (RING_UNIT_CHANNEL(unit_data, channel).flags < 0) {
        /* 0x00E76C68-0x00E76C6C: cmpi.w #0xa / bcc */
        if (channel >= RING_MAX_CHANNELS) {
            *status_ret = status_$ring_no_channels;     /* 0x00E76D48 */
            goto unlock;
        }
        channel++;
    }

    /* 0x00E76C7A-0x00E76C9A: both words zero-extended, cmpi.l / bls */
    if ((uint32_t)unit_data->pkt_type_cnt + (uint32_t)args->hdr.in.count
        > RING_MAX_PKT_TYPES) {
        *status_ret = status_$ring_no_channels;
        goto unlock;
    }

    /* 0x00E76C9E-0x00E76D18: subq.w #1 / bmi, then dbf */
    remaining = (int16_t)(args->hdr.in.count - 1);
    if (remaining >= 0) {
        k = 1;
        range = &args->body.types[0];
        do {
            /* 0x00E76CB2-0x00E76CC6: cmp.l / bls, unsigned */
            if (range->low > range->high) {
                *status_ret = status_$ring_invalid_svc_packet_type;
                goto unlock;
            }

            /* 0x00E76CCA-0x00E76CEC */
            if (ring_$pkt_type_overlaps(range->low, range->high,
                                        &RING_UNIT_PKT_TYPE(unit_data, 1),
                                        unit_data->pkt_type_cnt) < 0) {
                *status_ret = status_$ring_pkt_type_in_use;
                goto unlock;
            }

            /* 0x00E76CF0-0x00E76D0E: entry (k + cnt), word arithmetic */
            RING_UNIT_PKT_TYPE(unit_data,
                               (uint16_t)(k + unit_data->pkt_type_cnt)).low =
                range->low;
            RING_UNIT_PKT_TYPE(unit_data,
                               (uint16_t)(k + unit_data->pkt_type_cnt)).high =
                range->high;
            RING_UNIT_PKT_TYPE(unit_data,
                               (uint16_t)(k + unit_data->pkt_type_cnt)).channel =
                (int16_t)channel;

            /* 0x00E76D12-0x00E76D18 */
            k++;
            range++;
        } while (--remaining != -1);
    }

    /* 0x00E76D1C-0x00E76D20 */
    if (is_os < 0) {
        socket = RING_OS_SOCKET_ID;
    } else {
        /* 0x00E76D26-0x00E76D46: the two longwords 0x80008, 0x80400 */
        int8_t ok = SOCK_$ALLOCATE_USER(&sock_num, 8, 8, 8, 0x400);
        socket = sock_num;
        if (ok >= 0) {
            *status_ret = status_$ring_no_channels;     /* 0x00E76D48 */
            goto unlock;
        }
        /* 0x00E76D52-0x00E76D66: SOCK_$SOCKET_PTR (0xE28DB4) with the -4 bias */
        sock = SOCK_$DATA.socket_ptr[socket];
        sock->flags &= (uint16_t)~SOCK_FLAG_OPEN;
    }

    /* 0x00E76D6C-0x00E76D90 */
    chan = &RING_UNIT_CHANNEL(unit_data, channel);
    chan->asid = (int16_t)PROC1_$AS_ID;
    chan->socket_id = (int16_t)socket;
    chan->open_version = args->hdr.in.version;
    chan->flags = (boolean)0xFF;
    unit_data->pkt_type_cnt = (uint16_t)(unit_data->pkt_type_cnt
                                         + args->hdr.in.count);

unlock:
    /* 0x00E76D94-0x00E76D9E */
    ML_$EXCLUSION_STOP(&unit_data->rx_exclusion);

    if (*status_ret == status_$ok) {
        /* 0x00E76DA6-0x00E76DCA */
        args->body.channel = (int16_t)channel;
        sock = SOCK_$DATA.socket_ptr[socket];
        args->hdr.ec2_handle =
            ARCH_PTR_TO_VA(EC2_$REGISTER_EC1(&sock->ec, status_ret));
    } else {
        /* 0x00E76DCE-0x00E76DE2 */
        ML_$EXCLUSION_START(&unit_data->tx_exclusion);
        unit_data->open_count--;
        ML_$EXCLUSION_STOP(&unit_data->tx_exclusion);
    }
}
